// === Tab: mySketch ===
var constellation = [];
var n;
var d;
var emotionSys = new emotionSystem();

function setup() {
  createCanvas(500, 500);
  pixelDensity(1);
  //pixelDensity(displayDensity());
  n = 200;

  for (var i = 0; i <= n; i++) {
    constellation.push(new star());
  }
  strokeWeight(.75);
  stroke('#00FFaF');
}

function draw() {
  background('#000020');
  emotionSys.senseMovement([(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))])

  stroke(colorForEmotionalState(emotionSys.emotionalState));

  for (var i = 0; i < constellation.length; i++) {
    constellation[i].update();
    for (var j = 0; j < constellation.length; j++) {
      if (i > j) { // "if (i > j)" => to check one time distance between two stars
        d = constellation[i].loc.dist(constellation[j].loc); // Distance between two stars
        if (d <= width / 8) { // if d is less than width/10 px, we draw a line between the two stars
          line(constellation[i].loc.x, constellation[i].loc.y, constellation[j].loc.x, constellation[j].loc.y)
        }
      }
    }
  }

}

function star() {
  this.a = random(5 * TAU); // "5*TAU" => render will be more homogeneous
  this.r = random(width * .4, width * .25); // first position will looks like a donut
  this.loc = createVector(width / 2 + sin(this.a) * this.r, height / 2 + cos(this.a) * this.r);
  this.speed = createVector();
  this.speed = p5.Vector.random2D();
  //this.speed.random2D();
  this.bam = createVector();
  this.m;


  this.update = function() {
      this.bam = p5.Vector.random2D(); // movement of star will be a bit erractic
      //this.bam.random2D();
      this.bam.mult(0.45);
      this.speed.add(this.bam);
      // speed is done according distance between loc and the mouse :
      this.m = constrain(map(dist(this.loc.x, this.loc.y, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))), 0, width, 8, .05), .05, 8); // constrain => avoid returning "not a number"
      this.speed.normalize().mult(this.m);

      // No colision detection, instead loc is out of bound
      // it reappears on the opposite side :
      if (dist(this.loc.x, this.loc.y, width / 2, height / 2) > (width / 2) * 0.98) {
        if (this.loc.x < width / 2) {
          this.loc.x = width - this.loc.x - 4; // "-4" => avoid blinking stuff
        } else if (this.loc.x > width / 2) {
          this.loc.x = width - this.loc.x + 4; // "+4"  => avoid blinking stuff
        }
        if (this.loc.y < height / 2) {
          this.loc.y = width - this.loc.y - 4;
        } else if (this.loc.x > height / 2) {
          this.loc.y = width - this.loc.y + 4;
        }
      }
      this.loc = this.loc.add(this.speed);
    } // End of update()
} // End of class

function colorForEmotionalState(emotionalState) {
  if (emotionalState == null) return '#00FFaF';
  if (emotionalState > 0.5) return '#FF0040';
  if (emotionalState < 0.5) return '#64FE2E';

  return '#00FFaF';
}

function movementLengthsFromCoordinates(coordinates) {
  if (!coordinates || coordinates.length < 2) return [];

  const distnaces = [];
  for (var i = 0; i < coordinates.length - 1; i++) {
    var lastCoordinate = coordinates[i];
    var secondLastCoordinate = coordinates[i + 1];
    var distance = Math.sqrt(
      Math.pow(lastCoordinate[0] - secondLastCoordinate[0], 2) + Math.pow(lastCoordinate[1] - secondLastCoordinate[1], 2)
    );

    distnaces.push(distance);
  }

  return distnaces;
}

function distanceFromDistances(distances) {
  var amount = distances.length
  if (amount === 0) return null;

  var weightedSum = 0;

  for (var i=0; i < amount; i++) {
    weightedSum += (1 / (i + 1)) * distances[i];
  }

  return weightedSum / amount;
}

function emotionSystem() {
  this.movementMemoryLimit = 2;
  this.movements = [];
  this.emotionalState = 0.5;
  this.emotionFromMovement = function emotionFromMovement(distance) {
    return distance / Math.sqrt(1 + distance * distance);
  }

  this.senseMovement = function(newCoordinate) {
    if (newCoordinate[0] == null || newCoordinate[1] == null || (this.movements[0] && newCoordinate[0] === this.movements[0][0] && newCoordinate[1] === this.movements[0][1])) {
      return;
    }

    this.movements.unshift(newCoordinate);

    if (this.movements.length > this.movementMemoryLimit) {
      this.movements.pop();
    }

    this.recalculateState()
  }

  this.recalculateState = function() {
    var distances = movementLengthsFromCoordinates(this.movements);
    var distance = distanceFromDistances(distances);

    if (!distance) return 0.5;

    this.emotionalState = this.emotionFromMovement(distance - 1 * 10);
  }
}

